"""Library calls as nodes: a curated allowlist of public PINNeAPPle callables, their parameter forms generated by
introspection, and user-defined node types built on them.

Each entry of :data:`CALLS` names a callable (``module:attr``, or ``module:Class.method`` with constructor arguments)
plus curated metadata: title, category, references, which inputs come from ports (a series, a dataset, a surrogate,
a solution) and which parameters to leave out. The parameter schema is read from the signature (numbers, strings,
booleans, ``Literal`` choices, lists, dicts), so adding a capability is one entry, not a hand-written node.

Only entries of :data:`CALLS` run. A user-defined node (:func:`custom_spec`) picks an entry, fixes or hides some of
its parameters and gets a title; it is stored as data and can never name a callable that is not in the allowlist.

    for spec in library_specs(): REGISTRY.register(spec)        # done on import of pinneapple_flow.nodes
    custom_spec({"type": "custom.my_sobol", "base": "uq.sobol", "title": "Sobol (n=4096)",
                 "params": {"n": {"default": 4096, "hidden": True}}})
"""
from __future__ import annotations

import importlib
import inspect
import re
import typing
from dataclasses import dataclass, field
from typing import Any

import numpy as np

from pinneapple_core.workflows import StepFailed

from .registry import NodeSpec, Param, Port

_SAFE_DEFAULT = (int, float, str, bool, type(None))
_TYPE_ID = re.compile(r"^custom\.[a-z][a-z0-9_]{1,40}$")


@dataclass
class LibCall:
    key: str
    target: str                                      # "module:function" or "module:Class.method"
    title: str
    category: str
    description: str = ""
    refs: tuple[str, ...] = ()
    inputs: dict[str, tuple] = field(default_factory=dict)   # port -> (port type, argument, adapter[, required])
    exclude: tuple[str, ...] = ()
    overrides: dict[str, dict[str, Any]] = field(default_factory=dict)
    init: dict[str, Any] = field(default_factory=dict)          # constructor arguments for Class.method targets
    requires: tuple[str, ...] = ()
    output: str = "auto"                             # auto | dataset | series
    node_type: str = ""                              # a first-class node type name instead of lib.<key>


# -------------------------------------------------------------------------------------------- input adapters
def _series(v):
    from .runtime import load_artifact
    d = load_artifact(v)
    if "values" in d:
        a = np.asarray(d["values"], float)
        return a[:, 0] if a.ndim == 2 else a
    if "Y" in d:
        return np.asarray(d["Y"], float).ravel()
    raise StepFailed("expected a series or a dataset")


def _matrix(v):
    from .runtime import load_artifact
    d = load_artifact(v)
    for k in ("Y", "values", "A"):
        if k in d:
            return np.asarray(d[k], float)
    raise StepFailed("expected a dataset")


def _xy(v):
    from .runtime import load_artifact
    d = load_artifact(v)
    if "X" in d:
        return np.asarray(d["X"], float), np.asarray(d["Y"], float)
    if "A" in d:
        return np.asarray(d["A"], float), np.asarray(d["Y"], float)
    raise StepFailed("expected a dataset with inputs and outputs")


def _surrogate_fn(v):
    """A trained surrogate as ``f(P) -> scalar per row`` (the mean of the predicted field) and its input space."""
    import torch

    from . import learn
    from .runtime import load_artifact
    obj = load_artifact(v)
    if not isinstance(obj, dict) or "config" not in obj:
        raise StepFailed("expected a surrogate model")
    m = learn.load(obj)
    meta = obj.get("meta") or {}

    def f(P):
        with torch.no_grad():
            return m(torch.tensor(np.atleast_2d(np.asarray(P, np.float32)))).numpy().mean(1)
    space = {k: (float(a), float(b)) for k, a, b in zip(meta.get("param_names") or [], meta.get("lo") or [],
                                                        meta.get("hi") or [], strict=False)}
    return f, space


def _solution_values(v):
    from .nodes._common import load_solution
    s = load_solution(v)
    return s["values"][..., 0]


ADAPTERS = {"series": _series, "matrix": _matrix, "xy": _xy, "surrogate": _surrogate_fn,
            "solution_values": _solution_values}


# -------------------------------------------------------------------------------------------- introspection
def resolve(target: str):
    """The callable of an allowlisted target (module:attr or module:Class.method)."""
    mod, _, attr = target.partition(":")
    if not mod.startswith("pinneapple"):
        raise StepFailed(f"{target}: only pinneapple library callables can be nodes")
    obj = importlib.import_module(mod)
    for part in attr.split("."):
        obj = getattr(obj, part)
    return obj


def _kind_of(annotation, default) -> tuple[str, list | None]:
    a = annotation
    origin = typing.get_origin(a)
    if origin is typing.Literal:
        return "enum", list(typing.get_args(a))
    if isinstance(a, str):
        s = a.replace(" ", "")
        m = re.match(r"^Literal\[(.*)\]$", s)
        if m:
            return "enum", [x.strip("'\"") for x in m.group(1).split(",")]
        base = s.split("|")[0]
        a = {"int": int, "float": float, "str": str, "bool": bool, "list": list, "dict": dict, "tuple": tuple}.get(
            re.sub(r"\[.*", "", base).lower(), None)
    if origin in (list, tuple) or a in (list, tuple) or isinstance(default, (list, tuple)):
        return "list", None
    if origin is dict or a is dict or isinstance(default, dict):
        return "dict", None
    if a is bool or isinstance(default, bool):
        return "bool", None
    if a is int or (isinstance(default, int) and not isinstance(default, bool)):
        return "int", None
    if a is float or isinstance(default, float):
        return "float", None
    if a is str or isinstance(default, str):
        return "str", None
    if origin in (typing.Union, getattr(__import__("types"), "UnionType", None)):
        for x in typing.get_args(a):
            if x is not type(None):
                return _kind_of(x, default)
    return "", None


def introspect(call: LibCall) -> tuple[list[Param], list[str]]:
    """The parameters of a library call (those with simple types), and the names it could not expose."""
    fn = resolve(call.target)
    sig = inspect.signature(fn)
    try:
        hints = typing.get_type_hints(fn)
    except Exception:  # noqa: BLE001 - unresolvable annotations: fall back to the raw ones
        hints = {}
    params, skipped = [], []
    taken = {a.strip() for v in call.inputs.values() for a in v[1].split(",")} | set(call.exclude) | {
        "self", "cls", "out_dir"}
    for name, p in sig.parameters.items():
        if name in taken or p.kind in (p.VAR_POSITIONAL, p.VAR_KEYWORD):
            continue
        default = None if p.default is inspect.Parameter.empty else p.default
        if default is not None and not isinstance(default, (*_SAFE_DEFAULT, list, tuple, dict)):
            skipped.append(name)
            continue
        kind, choices = _kind_of(hints.get(name, p.annotation), default)
        if not kind:
            skipped.append(name)
            continue
        if isinstance(default, tuple):
            default = list(default)
        ov = call.overrides.get(name, {})
        params.append(Param(name, ov.get("kind", kind), ov.get("default", default), help=ov.get("help", ""),
                            choices=ov.get("choices", choices), minimum=ov.get("minimum"),
                            maximum=ov.get("maximum"), advanced=bool(ov.get("advanced", False))))
    return params, skipped


# -------------------------------------------------------------------------------------------- results
def summarize(ctx, result: Any, depth: int = 0) -> dict[str, Any]:
    """Turn whatever a library call returned into report entries and a JSON result."""
    import matplotlib.figure
    if isinstance(result, matplotlib.figure.Figure):
        ctx.figure(result, "result")
        return {"figure": True}
    if hasattr(result, "to_dict") and callable(result.to_dict) and depth == 0:
        try:
            return summarize(ctx, result.to_dict(), depth + 1)
        except Exception:  # noqa: BLE001 - fall through to the generic path
            pass
    if isinstance(result, dict):
        out = {}
        for k, v in list(result.items())[:200]:
            if isinstance(v, (int, float, np.floating, np.integer, bool, str)) and not isinstance(v, str) or (
                    isinstance(v, str) and len(v) < 200):
                ctx.metric(str(k), v)
                out[str(k)] = v
            elif isinstance(v, np.ndarray) and v.size <= 64:
                out[str(k)] = v.tolist()
            elif isinstance(v, (list, tuple)) and len(v) <= 64 and all(isinstance(x, (int, float, str))
                                                                       for x in v):
                out[str(k)] = list(v)
            elif isinstance(v, dict) and depth < 2:
                out[str(k)] = summarize(ctx, v, depth + 1) if depth == 0 else {kk: vv for kk, vv in list(v.items())
                                                                                [:50] if isinstance(vv, (int,
                                                                                                         float,
                                                                                                         str))}
        return out
    if isinstance(result, (int, float, np.floating, np.integer)):
        ctx.metric("result", float(result))
        return {"result": float(result)}
    if isinstance(result, str):
        ctx.summary(result[:500])
        return {"result": result[:2000]}
    if isinstance(result, np.ndarray):
        ctx.metric("shape", list(result.shape))
        if result.size:
            ctx.metric("mean", float(np.mean(result)))
        return {"shape": list(result.shape)}
    if isinstance(result, (list, tuple)):
        return {"items": [summarize(ctx, x, depth + 1) if isinstance(x, dict) else str(x)[:200]
                          for x in list(result)[:20]]}
    attrs = {k: getattr(result, k) for k in dir(result) if not k.startswith("_")
             and isinstance(getattr(result, k, None), (int, float, str, bool, np.floating))}
    if attrs:
        return summarize(ctx, attrs, depth + 1)
    text = str(result)
    ctx.summary(text[:500])
    return {"result": text[:2000]}


def _runner(call: LibCall, fixed: dict[str, Any] | None = None):
    def run(ctx, inputs, params):
        fn = resolve(call.target)
        kw = {k: v for k, v in params.items() if v is not None}
        kw.update(fixed or {})
        if "out_dir" in inspect.signature(fn).parameters:         # files go to this node's run folder, never a path
            kw["out_dir"] = str(ctx.workdir)                     # taken from the flow document
        for port, (_t, arg, adapter, *_req) in call.inputs.items():
            if inputs.get(port) is None:
                continue
            val = ADAPTERS[adapter](inputs[port])
            if adapter == "xy":
                a, b = arg.split(",")
                kw[a.strip()], kw[b.strip()] = val
            elif adapter == "surrogate":
                kw[arg], space = val
                kw.setdefault("space", space)
            else:
                kw[arg] = val
        if "." in call.target.split(":", 1)[1]:                    # Class.method: build with init, then call
            cls_path, meth = call.target.rsplit(".", 1)
            obj = resolve(cls_path)(**call.init)
            res = getattr(obj, meth)(**kw)
        else:
            res = fn(**kw)
        ctx.log(f"called {call.target}")
        for k in call.refs:
            from .decisions import Decision
            from .references import cite
            ctx.report["decisions"].append(Decision(topic="method", what=f"{call.title}: {call.target}",
                                                    decided_by={"kind": "user", "id": "node choice"},
                                                    references=cite(k), node=ctx.node_id).to_dict())
        out = summarize(ctx, res)
        outputs = {"result": out}
        if call.output == "series" and isinstance(res, np.ndarray):
            s = ctx.save_npz("series", t=np.arange(len(res), dtype=float), values=np.asarray(res, float).reshape(
                len(res), -1))
            s.update({"channels": ["y"]})
            outputs["series"] = s
        return outputs
    return run


def _available(call: LibCall):
    def check():
        for mod in (call.target.split(":")[0], *call.requires):
            try:
                importlib.import_module(mod)
            except Exception as exc:  # noqa: BLE001
                return False, f"needs {mod} ({type(exc).__name__}: {str(exc)[:120]})"
        return True, ""
    return check


def spec_for(call: LibCall, *, type_: str | None = None, title: str | None = None,
             fixed: dict[str, Any] | None = None, defaults: dict[str, Any] | None = None,
             hidden: tuple[str, ...] = ()) -> NodeSpec:
    try:
        params, skipped = introspect(call)
    except Exception as exc:  # noqa: BLE001 - the library part is not importable here: an unavailable node
        params, skipped = [], [f"(signature unavailable: {type(exc).__name__})"]
    out = []
    for p in params:
        if p.name in hidden or p.name in (fixed or {}):
            continue
        if defaults and p.name in defaults:
            p.default = defaults[p.name]
        out.append(p)
    ins = [Port(port, v[0], required=v[3] if len(v) > 3 else True) for port, v in call.inputs.items()]
    outs = [Port("result", "metrics")] + ([Port("series", "series", required=False)] if call.output == "series"
                                         else [])
    desc = call.description + (f" (not exposed: {', '.join(skipped)})" if skipped else "")
    return NodeSpec(type=type_ or call.node_type or f"lib.{call.key}", title=title or call.title, category=call.category,
                    fn=_runner(call, fixed), inputs=ins, outputs=outs, params=out, description=desc,
                    calls=" ".join([call.target, *wrapped(call)]), available_fn=_available(call))


_LIB = re.compile(r"\b(?:from|import) (pinneapple[a-z_]*(?:\.[a-z_]+)*)")


def wrapped(call: LibCall) -> list[str]:
    """For a JSON-argument wrapper (``pinneapple_flow.wrappers``): the library modules it imports, read from its
    source, so the node's ``calls`` (and the coverage table) name the capability rather than the wrapper."""
    mod, _, name = call.target.partition(":")
    if not mod.startswith("pinneapple_flow."):
        return []
    try:
        src = inspect.getsource(resolve(call.target))
    except (OSError, TypeError, ImportError, AttributeError):
        return []
    out = [m for m in _LIB.findall(src) if not m.startswith(("pinneapple_flow", "pinneapple_core.workflows"))]
    out += [f"pinneapple.{a}" for a in re.findall(r"\bpp\.([a-z_]+)\(", src)]      # import pinneapple as pp
    if "_solver(" in src:
        out.append("pinneapple_simulation.numerical_solvers.registry")
    return sorted(set(out))


# -------------------------------------------------------------------------------------------- user-defined nodes
def custom_spec(doc: dict[str, Any]) -> NodeSpec:
    """A user-defined node type: ``{"type": "custom.<name>", "base": <CALLS key>, "title", "category",
    "description", "params": {name: {"default": v, "hidden": bool}}}``. ValueError when it names anything but an
    allowlisted call or sets a parameter the call does not have."""
    t = str(doc.get("type", ""))
    if not _TYPE_ID.match(t):
        raise ValueError("a custom node type is 'custom.' + lower-case letters, digits and _ (2-41 characters)")
    base = CALLS.get(str(doc.get("base", "")))
    if base is None:
        raise ValueError(f"base {doc.get('base')!r} is not a registered library call")
    params, _ = introspect(base)
    names = {p.name: p for p in params}
    fixed, defaults, hidden = {}, {}, []
    for k, cfg in (doc.get("params") or {}).items():
        if k not in names:
            raise ValueError(f"{base.key} has no parameter {k!r}")
        cfg = cfg if isinstance(cfg, dict) else {"default": cfg}
        if "default" in cfg:
            err = names[k].check(cfg["default"])
            if err:
                raise ValueError(err)
            (fixed if cfg.get("hidden") else defaults)[k] = cfg["default"]
        if cfg.get("hidden"):
            hidden.append(k)
    title = str(doc.get("title") or t)[:80]
    spec = spec_for(base, type_=t, title=title, fixed=fixed, defaults=defaults, hidden=tuple(hidden))
    spec.category = str(doc.get("category") or "Custom")[:40]
    if doc.get("description"):
        spec.description = str(doc["description"])[:1000] + f" (built on {base.target})"
    return spec


def library_specs() -> list[NodeSpec]:
    return [spec_for(c) for c in CALLS.values()]


def auto_specs() -> list[NodeSpec]:
    """Nodes generated from the public API (:mod:`pinneapple_flow.autocalls`, committed ``autocalls.json``): the
    forms come from the recorded signatures, so the modules are imported only when a node runs."""
    from .autocalls import load
    out = []
    for e in load()["calls"]:
        call = LibCall(e["key"], e["target"], e["title"], "Library: " + e["module"].split(".")[0].removeprefix(
            "pinneapple_").replace("pinneapple", "pp"), e.get("description", ""))
        params = [Param(p["name"], p["kind"], p["default"], choices=p.get("choices"),
                        help="required" if p.get("required") else "") for p in e["params"]]
        check = e.get("check", "")
        missing = re.search(r"(?:No module named|requires the) '([^']+)'", check)

        def avail(missing=missing):
            return (False, f"needs {missing.group(1)}") if missing else (True, "")
        desc = (e.get("description") or e["target"]) + (f" [checked: {check}]" if check else "")
        out.append(NodeSpec(type=e["key"], title=e["title"], category=call.category, fn=_runner(call),
                            inputs=[], outputs=[Port("result", "metrics")], params=params, description=desc,
                            calls=e["target"], available_fn=avail))
    return out


# -------------------------------------------------------------------------------------------- the allowlist
CALLS: dict[str, LibCall] = {}


def add(*calls: LibCall) -> None:
    for c in calls:
        if c.key in CALLS:
            raise ValueError(f"duplicate library call {c.key!r}")
        CALLS[c.key] = c


from . import libcalls_catalog  # noqa: E402,F401  (fills CALLS)
